var crypto = require('crypto')
return {
  new_uuid: crypto.randomUUID()
};

// Get all messages from the database SELECT query
const allMessages = $input.all().map(msg => msg.json);

// Format conversation history and include Epistemologist feedback if available
const history = allMessages
  .map(m => {
    let msgBlock = `[${m.agent_name} - Iteration ${m.iteration}]: ${m.content}`;

    // Append fact-checker feedback if it exists for this message
    if (m.fact_check_feedback) {
      msgBlock += `\n\n[Epistemologist Fact-Check on ${m.agent_name}]:\n${m.fact_check_feedback}`;
    }

    return msgBlock;
  })
  .join('\n\n--------------------------------------------------\n\n');

// Return updated payload that will flow to the next iteration
return [{
  json: {
    user_query: $('Prepare Payload').first().json.user_query,
    life_context: $('Prepare Payload').first().json.life_context,
    session_id: $('Prepare Payload').first().json.session_id,
    max_loops: $('Prepare Payload').first().json.max_loops,
    current_iteration: $('Prepare Payload').first().json.current_iteration + 1,
    conversation_history: history,
    chat_id: $('Prepare Payload').first().json.chat_id
  }
}];

