// ═══════════════════════════════════════════════════════════
// STEP 1: Split raw LLM output into Telegram-safe chunks
// ═══════════════════════════════════════════════════════════

let text = String($json.output || '');
const MAX_LEN = 3800; // buffer under Telegram's 4096 limit

// Split at ### headings, ═══ dividers, or paragraph breaks
let chunks = text.split(/(?=^### |\n(?=═{3,}\n))/m);

// Sub-split any chunk still over the limit at paragraph breaks
const refined = [];
for (const chunk of chunks) {
  if (chunk.length <= MAX_LEN) {
    refined.push(chunk);
  } else {
    const paragraphs = chunk.split(/(?=\n\n)/);
    for (const p of paragraphs) {
      refined.push(p);
    }
  }
}

// Bin-pack into parts, each under MAX_LEN
const parts = [];
let current = '';

for (const chunk of refined) {
  if (current.length > 0 && current.length + chunk.length > MAX_LEN) {
    parts.push(current.trim());
    current = chunk;
  } else {
    current += chunk;
  }
}
if (current.trim().length > 0) {
  parts.push(current.trim());
}

// ═══════════════════════════════════════════════════════════
// STEP 2: MarkdownV2 Escape Function
// ═══════════════════════════════════════════════════════════

function escapeForMarkdownV2(text) {
  if (!text) return '';

  // --- Phase 1: Extract code blocks (literal in MarkdownV2) ---
  const codeBlocks = [];

  // Protect fenced code blocks: ```content```
  text = text.replace(/```([\s\S]*?)```/g, (match) => {
    codeBlocks.push(match);
    return `\x00CODEBLOCK${codeBlocks.length - 1}\x00`;
  });

  // Protect inline code: `content`
  text = text.replace(/`([^`]+)`/g, (match) => {
    codeBlocks.push(match);
    return `\x00CODEBLOCK${codeBlocks.length - 1}\x00`;
  });

  // --- Phase 2: Escape ALL special characters ---
  text = text.replace(/([_*\[\]()~>#\+\-=|{}.!\\])/g, '\\$1');

  // --- Phase 3: Un-escape intentional formatting markers ---

  // Bold: \*\*text\*\* → *text*
  text = text.replace(/\\\*\\\*(.*?)\\\*\\\*/g, '*$1*');

  // Italic: \_text\_ → _text_
  text = text.replace(/\\_(.*?)\\_/g, '_$1_');

  // Blockquote: \> at line start → >
  text = text.replace(/^\\>/gm, '>');

  // --- Phase 4: Restore code blocks (untouched) ---
  for (let i = 0; i < codeBlocks.length; i++) {
    text = text.replace(`\x00CODEBLOCK${i}\x00`, codeBlocks[i]);
  }

  return text;
}

// ═══════════════════════════════════════════════════════════
// STEP 3: Escape each part, return one item per chunk
// ═══════════════════════════════════════════════════════════

return parts
  .map(p => escapeForMarkdownV2(p))
  .filter(p => p.trim().length > 0)
  .map((text, i) => ({ json: { text, partIndex: i + 1 } }));

